 * when the API sent one; "" when the amount is missing or the currency is unknown — never an
 * invented symbol, never a USD default.
 */
export function formatPrice(amount, money, platformFormatted) {
    if (platformFormatted)
        return platformFormatted;
    if (amount == null || amount === "" || !money.currency)
        return "";
