}
// ---- id collection for the second and third reads ---------------------------------------------
/** The variant ids the items reference — the second read's `variantIds`. */
export function collectVariantIds(items) {
    return unique(items.flatMap((i) => (i.priceVariants?.variants ?? []).map((v) => v.variantId)));
}
/** The modifier-group ids the items reference — the second read's `modifierGroupIds`. */
export function collectGroupIds(items) {
    return unique(items.flatMap((i) => (i.modifierGroups ?? []).map(rawId)));
}
/** The modifier ids the groups reference — the third read's `modifierIds`. */
export function collectModifierIds(groups) {
    return unique(groups.flatMap((g) => (g.modifiers ?? []).map(rawId)));
}
/** Whether any item carries a label — the labels list is read only then. */
export function anyLabels(items) {
