/** The rule's shape, in Wix's precedence (NO_LIMIT → CHOOSE_ONE → CHOOSE_X → AT_LEAST_ONE → AT_LEAST_X → UP_TO_X → BETWEEN). */
export function ruleType(rule) {
    const { required, minSelections: min, maxSelections: max } = rule;
    if (!required && min < 1 && (max ? max < 1 : true))
        return "NO_LIMIT";
    if ((required && min === 1 && max === 1) || (!required && min === 0 && max === 1))
        return "CHOOSE_ONE";
    if (required && max && min === max)
        return "CHOOSE_X";
    if (required && min === 1 && max == null)
        return "CHOOSE_AT_LEAST_ONE";
    if (required && min > 1 && max == null)
        return "CHOOSE_AT_LEAST_X";
    if (!required && min === 0 && max && max > 1)
        return "CHOOSE_UP_TO_X";
    if (required && max && min > 0 && max > min)
